package dev.gamersclt.batcaverna.nativeapp;
import org.json.*;
import java.util.*;
final class ProfileAchievements {
 static JSONArray calculate(JSONArray items)throws JSONException{int games=0,media=0,finished=0,plat=0,perfect=0,high=0,backlog=0,playing=0;double hours=0;Set<String> platforms=new HashSet<>(),genres=new HashSet<>();Map<String,JSONObject> gamesById=new HashMap<>();for(int i=0;i<items.length();i++){JSONObject x=items.optJSONObject(i);if(x==null)continue;boolean game="jogos".equals(x.optString("categoria"));String s=x.optString("status","").toLowerCase(Locale.ROOT);if(game){games++;gamesById.put(x.optString("nome"),x);hours+=x.optDouble("horas",0);if(s.contains("zerado")||s.contains("platina"))finished++;if(s.contains("platina"))plat++;if(x.optDouble("conquistas")>=100)perfect++;if(x.optDouble("nota")>=9)high++;if(s.matches(".*(backlog|pretendo|a considerar).*"))backlog++;if(s.matches(".*(progresso|jogando).*"))playing++;String platform=x.optString("plataforma","").trim().toLowerCase(Locale.ROOT);if(!platform.isEmpty())platforms.add(platform);}else media++;Object gs=x.opt("generos");if(gs instanceof JSONArray){JSONArray a=(JSONArray)gs;for(int k=0;k<a.length();k++){String g=a.optString(k).trim().toLowerCase(Locale.ROOT);if(!g.isEmpty())genres.add(g);}}else if(gs instanceof String)for(String g:((String)gs).split("[,|]"))if(!g.trim().isEmpty())genres.add(g.trim().toLowerCase(Locale.ROOT));}
boolean[] unlocked={games>=1,games>=10,games>=25,games>=50,games>=100,finished>=10,finished>=5,finished>=25,plat>=5,plat>=10,plat>=20,hours>=100,hours>=250,hours>=500,media>=10,media>=25,perfect>=1,perfect>=5,platforms.size()>=3,platforms.size()>=5,genres.size()>=5,high>=10,games+media>=150,games+media>=250,genres.size()>=10,platforms.size()>=8,perfect>=10,hours>=1000,high>=25,games>=10&&backlog==0,games+media>=500,games+media>=50};
String[] names={"Primeiro passo","Colecionador","Veterano","Lenda CLT","Biblioteca lendária","Finalizador","No ritmo","Máquina de zerar","Caçador de Platinas","Veterano dos CLTs","Rei das Platinas","Maratonista","Longa jornada","Vida de gamer","Cinéfilo","Sessão infinita","100%","Caçador de 100%","Diversificado","Multiplataforma","Explorador","Crítico exigente","Colecionador de histórias","Acervo monstruoso","Universo expandido","Explorador de plataformas","Colecionador de 100%","Mil horas","Crítico profissional","Backlog limpo","Acervo colossal","Mestre multimídia"};
JSONArray out=new JSONArray();for(int i=0;i<names.length;i++)out.put(new JSONObject().put("id",i).put("name",names[i]).put("unlocked",unlocked[i]));return out;}
}
